@ServerEndpoint("/ws/chat")          // no configurator
public class ChatEndpoint {
    @Autowired
    private ChatService service;

    @OnOpen
    public void open(Session s) {
        service.joined(s);
    }
}

@Component
public class ChatHandler extends TextWebSocketHandler {
    private static final Set<WebSocketSession> ALL = new CopyOnWriteArraySet<>();
    private String user;

    @Override
    public void afterConnectionEstablished(WebSocketSession s) {
        user = (String) s.getAttributes().get("user");   // put there during the handshake
        ALL.add(s);
    }

    @Override
    protected void handleTextMessage(WebSocketSession s, TextMessage m) throws Exception {
        for (WebSocketSession other : ALL) {
            other.sendMessage(new TextMessage(user + ": " + m.getPayload()));
        }
    }
}

